 1	/**
 2	 * Notes Collected View — Repo Parallelizer GUI.
 3	 *
 4	 * Two-panel layout:
 5	 *   - Left sidebar: all workspaces grouped by project (collapsible groups).
 6	 *     Workspaces with existing notes are visually distinguished with a
 7	 *     `.has-notes` class on the sidebar item.
 8	 *   - Right main panel: editable note cards for workspaces with non-empty notes.
 9	 *     On initial load only non-empty note cards are rendered.
10	 *     Clicking a sidebar item for a workspace with a card scrolls to it.
11	 *     Clicking a sidebar item for a workspace without a card creates a new
12	 *     empty card and focuses the textarea.
13	 *     Each card auto-saves after 1000 ms of inactivity (debounce).
14	 *     Saving an empty note removes the card and clears the sidebar indicator.
15	 *
16	 * Data flow:
17	 *   1. `api.notes.list()` fetches the raw PascalCase `GET /api/notes` response.
18	 *   2. `normaliseNotesResponse()` converts it to a camelCase
19	 *      `{ projects: [{ projectId, projectName, workspaces: [{ workspaceId, notes }] }] }`
20	 *      structure used throughout the view.
21	 *   3. A `notesMap` (`Map<"${projectId}|${workspaceId}", string>`) mirrors the
22	 *      current note text in memory, keeping sidebar indicators and newly-created
23	 *      cards in sync with saves without re-fetching from the server.
24	 *
25	 * All dynamic text is set via `textContent` (never `innerHTML`) for XSS safety.
26	 *
27	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
28	 * @param {Object}      _params   - Route params (none for this route).
29	 */
30	
31	import { api }                    from '../api.js';
32	import { showToast }              from '../components/toast.js';
33	import { normaliseNotesResponse } from '../utils/normalise.js';
34	
35	// ---------------------------------------------------------------------------
36	// Internal DOM helpers
37	// ---------------------------------------------------------------------------
38	
39	/**
40	 * Find a note card in the main panel by project + workspace ID using dataset
41	 * attributes (avoids CSS-escaping concerns with arbitrary ID strings).
42	 *
43	 * @param {HTMLElement} mainPanel
44	 * @param {string}      projectId
45	 * @param {string}      workspaceId
46	 * @returns {HTMLElement|null}
47	 */
48	function findCard(mainPanel, projectId, workspaceId) {
49	    for (const card of mainPanel.querySelectorAll('.notes-card')) {
50	        if (card.dataset.projectId === projectId && card.dataset.workspaceId === workspaceId) {
51	            return card;
52	        }
53	    }
54	    return null;
55	}
56	
57	/**
58	 * Find a sidebar list item by project + workspace ID.
59	 *
60	 * @param {HTMLElement} sidebar
61	 * @param {string}      projectId
62	 * @param {string}      workspaceId
63	 * @returns {HTMLElement|null}
64	 */
65	function findSidebarItem(sidebar, projectId, workspaceId) {
66	    for (const item of sidebar.querySelectorAll('.notes-sidebar-item')) {
67	        if (item.dataset.projectId === projectId && item.dataset.workspaceId === workspaceId) {
68	            return item;
69	        }
70	    }
71	    return null;
72	}
73	
74	// ---------------------------------------------------------------------------
75	// Empty-state management
76	// ---------------------------------------------------------------------------
77	
78	/**
79	 * Show or hide the "no notes" empty-state message based on whether the main
80	 * panel contains any note cards.
81	 *
82	 * @param {HTMLElement} mainPanel
83	 */
84	function refreshEmptyState(mainPanel) {
85	    const existing = mainPanel.querySelector('.notes-empty-state');
86	    const hasCards = mainPanel.querySelector('.notes-card') !== null;
87	    if (hasCards && existing) {
88	        existing.remove();
89	    } else if (!hasCards && !existing) {
90	        const p = document.createElement('p');
91	        p.className = 'notes-empty-state';
92	        p.textContent = 'No workspace notes yet. Click a workspace in the sidebar to add one.';
93	        mainPanel.appendChild(p);
94	    }
95	}
