98	// Sidebar builder
99	// ---------------------------------------------------------------------------

 98	// Sidebar builder
 99	// ---------------------------------------------------------------------------
100	
101	/**
102	 * Build the left sidebar listing all workspaces grouped by project.
103	 *
104	 * Each project is rendered as a `<details>` element (open by default) so
105	 * groups are collapsible. Sidebar items with existing notes carry the
106	 * `.has-notes` modifier class.
107	 *
108	 * @param {Array<{ projectId: string, projectName: string,
109	 *   workspaces: Array<{ workspaceId: string, notes: string }> }>} projects
110	 * @param {function(string, string): void} onItemClick
111	 *   Called with (projectId, workspaceId) when a sidebar button is clicked.
112	 * @returns {HTMLElement}
113	 */
114	function buildSidebar(projects, onItemClick) {
115	    const aside = document.createElement('aside');
116	    aside.className = 'notes-sidebar';
117	
118	    const heading = document.createElement('h2');
119	    heading.className = 'notes-sidebar-heading';
120	    heading.textContent = 'Workspaces';
121	    aside.appendChild(heading);
122	
123	    for (const project of projects) {
124	        const details = document.createElement('details');
125	        details.className = 'notes-sidebar-group';
126	
127	        const summary = document.createElement('summary');
128	        summary.className = 'notes-sidebar-group-title';
129	        summary.textContent = project.projectName || project.projectId;
130	        details.appendChild(summary);
131	
132	        const ul = document.createElement('ul');
133	        ul.className = 'notes-sidebar-list';
134	
135	        for (const ws of project.workspaces) {
136	            const li = document.createElement('li');
137	            li.className = 'notes-sidebar-item';
138	            li.dataset.projectId   = project.projectId;
139	            li.dataset.workspaceId = ws.workspaceId;
140	            if (ws.notes) {
141	                li.classList.add('has-notes');
142	            }
143	
144	            const btn = document.createElement('button');
145	            btn.type = 'button';
146	            btn.className = 'notes-sidebar-btn';
147	            btn.textContent = ws.workspaceId;
148	            btn.addEventListener('click', () => onItemClick(project.projectId, ws.workspaceId));
149	
150	            li.appendChild(btn);
151	            ul.appendChild(li);
152	        }
153	
154	        details.appendChild(ul);
155	        aside.appendChild(details);
156	    }
157	
158	    return aside;
159	}
